INSERT INTO public.scraper_sources (id, source_name, society, base_url, default_event_type, pagination_type, pagination_template, max_pages_hint, detail_is_multipage, active, extraction_instructions) VALUES
  (162, 'ESGE Days', 'ESGE', 'https://www.esgedays.org/', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'Congress site only (esgedays.org); never fetch esge.com (terms forbid automated access). Home page ''Essential Information'' lists the key dates and ''April 29 - May 1, 2027: ESGE Days 2027 in Lisbon, Portugal'' (the one-day pre-course line comes first). Fees: text grid on /registration/register-now. Abstract deadline: abstracts page ''November 17, 2026: Deadline for abstract submissions''. Venue: how-to-get page ''Venue Address : Lisbon Congress Centre''.'),
  (165, 'EHA Congress', 'EHA', 'https://ehaweb.org/connect-network/eha2027-congress', 'conference', 'single_page', NULL, 1, FALSE, TRUE, 'ehaweb.org only; never fetch congress.ehaweb.org (robots Disallow: /). EHA2027 page shows ''June 10-13, 2027 | Barcelona, Spain''; fee grids (Hybrid / Virtual, Early / Regular / Late, EUR incl. VAT) on /eha2027-registration; abstract key dates on /eha2027-abstract-submission; venue under ''Location'' on /eha2027-details-and-deadlines. ehaweb.org answers 403 to some clients: use fetch_html with the browser fallback.')
